prompts:
Redesign the app and update any design system specifications (or add to @README.md) to match this html design: <!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Solar Haze Portal</title>
    <link rel="preconnect" href="https://fonts.googleapis.com">
    <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
    <link href="https://fonts.googleapis.com/css2?family=Outfit:wght@300;500&family=DM+Serif+Display&family=JetBrains+Mono:wght@300&display=swap" rel="stylesheet">
    <style>
        :root {
            --solar-glow: #ff9d6c;
            --haze-pink: #f0a2b1;
            --deep-cosmos: #2e1a47;
            --clay-surface: #ffffff;
            --glass-shine: rgba(255, 255, 255, 0.25);
            --soft-shadow: rgba(74, 34, 122, 0.15);
        }

        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
            -webkit-font-smoothing: antialiased;
        }

        body {
            background: radial-gradient(circle at 20% 30%, #4a227a 0%, #2e1a47 100%);
            height: 100vh;
            display: flex;
            align-items: center;
            justify-content: center;
            overflow: hidden;
            font-family: 'Outfit', sans-serif;
            color: #4a227a;
        }

        /* Solar Haze Background Elements */
        .orb {
            position: absolute;
            border-radius: 50%;
            filter: blur(80px);
            z-index: 0;
            animation: drift 20s infinite alternate ease-in-out;
        }

        .orb-1 {
            width: 400px;
            height: 400px;
            background: var(--solar-glow);
            top: -100px;
            right: -50px;
            opacity: 0.4;
        }

        .orb-2 {
            width: 500px;
            height: 500px;
            background: var(--haze-pink);
            bottom: -150px;
            left: -100px;
            opacity: 0.3;
            animation-delay: -5s;
        }

        /* Login Sculpture */
        .login-sculpture {
            position: relative;
            z-index: 10;
            width: 100%;
            max-width: 440px;
            padding: 3rem;
            /* Claymorphism Foundation */
            background: var(--clay-surface);
            border-radius: 60px;
            box-shadow: 
                35px 35px 70px var(--soft-shadow),
                inset 10px 10px 20px rgba(255, 255, 255, 0.8),
                inset -10px -10px 20px rgba(74, 34, 122, 0.05);

            /* Glassmorphism Layering */
            backdrop-filter: blur(5px);
            border: 1px solid rgba(255, 255, 255, 0.4);

            display: flex;
            flex-direction: column;
            gap: 2rem;
            transform: translateY(20px);
            opacity: 0;
            animation: slideUp 1.2s cubic-bezier(0.22, 1, 0.36, 1) forwards;
        }

        header {
            text-align: center;
        }

        h1 {
            font-family: 'DM Serif Display', serif;
            font-size: 2.8rem;
            line-height: 1;
            margin-bottom: 0.5rem;
            background: linear-gradient(135deg, #4a227a, #ff6b6b);
            -webkit-background-clip: text;
            -webkit-text-fill-color: transparent;
        }

        p {
            font-weight: 300;
            opacity: 0.6;
            font-size: 0.95rem;
            letter-spacing: 0.02em;
        }

        /* Neumorphic Inputs */
        .input-group {
            display: flex;
            flex-direction: column;
            gap: 1.5rem;
        }

        .field-container {
            position: relative;
        }

        .field-container label {
            display: block;
            margin-left: 1.5rem;
            margin-bottom: 0.6rem;
            font-size: 0.75rem;
            font-family: 'JetBrains Mono', monospace;
            text-transform: uppercase;
            letter-spacing: 0.1em;
            opacity: 0.5;
        }

        input {
            width: 100%;
            padding: 1.2rem 1.8rem;
            border: none;
            border-radius: 30px;
            background: #f7f3ff;
            /* Neumorphic Inset */
            box-shadow: 
                inset 6px 6px 12px rgba(0, 0, 0, 0.05),
                inset -6px -6px 12px rgba(255, 255, 255, 0.8);
            font-family: 'Outfit', sans-serif;
            font-size: 1rem;
            color: var(--deep-cosmos);
            transition: all 0.4s ease;
            outline: none;
        }

        input:focus {
            box-shadow: 
                inset 2px 2px 5px rgba(0, 0, 0, 0.05),
                inset -2px -2px 5px rgba(255, 255, 255, 0.8),
                0 0 0 3px rgba(255, 157, 108, 0.2);
            background: #ffffff;
        }

        /* Claymorphic Button */
        .btn-ascend {
            margin-top: 1rem;
            padding: 1.2rem;
            border: none;
            border-radius: 30px;
            background: linear-gradient(135deg, #ff9d6c 0%, #f0a2b1 100%);
            color: white;
            font-family: 'Outfit', sans-serif;
            font-weight: 500;
            font-size: 1.1rem;
            cursor: pointer;
            /* Claymorphism shadows */
            box-shadow: 
                0 15px 30px rgba(255, 157, 108, 0.3),
                inset 4px 4px 8px rgba(255, 255, 255, 0.4),
                inset -4px -4px 8px rgba(0, 0, 0, 0.1);
            transition: all 0.3s cubic-bezier(0.175, 0.885, 0.32, 1.275);
        }

        .btn-ascend:hover {
            transform: scale(1.02) translateY(-3px);
            box-shadow: 
                0 20px 40px rgba(255, 157, 108, 0.4),
                inset 6px 6px 12px rgba(255, 255, 255, 0.5);
        }

        .btn-ascend:active {
            transform: scale(0.98);
            box-shadow: 
                0 5px 15px rgba(255, 157, 108, 0.3),
                inset 10px 10px 20px rgba(0, 0, 0, 0.1);
        }

        footer {
            text-align: center;
            margin-top: 1rem;
        }

        footer a {
            color: inherit;
            text-decoration: none;
            font-size: 0.85rem;
            opacity: 0.4;
            transition: opacity 0.3s ease;
        }

        footer a:hover {
            opacity: 1;
        }

        /* Animations */
        @keyframes drift {
            from { transform: translate(0, 0) scale(1); }
            to { transform: translate(40px, 60px) scale(1.1); }
        }

        @keyframes slideUp {
            from { transform: translateY(50px); opacity: 0; }
            to { transform: translateY(0); opacity: 1; }
        }

        /* High-Performance Grain Overlay */
        .grain {
            position: fixed;
            top: 0; left: 0;
            width: 100%; height: 100%;
            pointer-events: none;
            z-index: 100;
            opacity: 0.04;
            background: url("data:image/svg+xml,%3Csvg viewBox='0 0 200 200' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='noiseFilter'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.65' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23noiseFilter)'/%3E%3C/svg%3E");
        }

        /* Cosmic Sparkles */
        .sparkle {
            position: absolute;
            background: white;
            border-radius: 50%;
            opacity: 0.3;
            pointer-events: none;
        }
    </style>
</head>
<body>

    <div class="grain"></div>
    <div class="orb orb-1"></div>
    <div class="orb orb-2"></div>

    <main class="login-sculpture">
        <header>
            <h1>Solaris</h1>
            <p>Return to the warmth of the void.</p>
        </header>

        <form class="input-group" onsubmit="event.preventDefault();">
            <div class="field-container">
                <label for="identity">Identity</label>
                <input type="text" id="identity" placeholder="Stardust traveler" autocomplete="off">
            </div>

            <div class="field-container">
                <label for="key">Vibration Key</label>
                <input type="password" id="key" placeholder="•••>
            </div>

            <button type="submit" class="btn-ascend">Ascend to Portal</button>
        </form>

        <footer>
            <a href="#">Forgot your resonance?</a>
        </footer>
    </main>

    <script>
        // Add subtle interactive particles
        const container = document.body;
        for (let i = 0; i < 20; i++) {
            const sparkle = document.createElement('div');
            sparkle.className = 'sparkle';
            const size = Math.random() * 3 + 1;
            sparkle.style.width = `${size}px`;
            sparkle.style.height = `${size}px`;
            sparkle.style.left = `${Math.random() * 100}%`;
            sparkle.style.top = `${Math.random() * 100}%`;
            sparkle.style.animation = `drift ${Math.random() * 10 + 10}s infinite linear`;
            container.appendChild(sparkle);
        }

        // Magnetic button effect
        const btn = document.querySelector('.btn-ascend');
        btn.addEventListener('mousemove', (e) => {
            const rect = btn.getBoundingClientRect();
            const x = e.clientX - rect.left;
            const y = e.clientY - rect.top;

            const centerX = rect.width / 2;
            const centerY = rect.height / 2;

            const deltaX = (x - centerX) / 8;
            const deltaY = (y - centerY) / 8;

            btn.style.transform = `translate(${deltaX}px, ${deltaY}px) scale(1.02)`;
        });

        btn.addEventListener('mouseleave', () => {
            btn.style.transform = `translate(0, 0) scale(1)`;
        });
    </script>
</body>
</html>
